sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    // Clear existing messages
    g_form.clearMessages();

    switch (newValue) {
        case 'once daily':
            g_form.addInfoMessage("Take once every 24 hours.");
            break;
        case 'twice daily':
            g_form.addInfoMessage("Take every 12 hours.");
            break;
        case 'thrice daily':
            g_form.addInfoMessage("Take every 8 hours.");
            break;
        case 'etc':
            g_form.addInfoMessage("Take only when required.");
            break;
        default:
            g_form.addInfoMessage("Please follow your healthcare provider's instructions.");
    }
}
